function mini(type){const e=getEra();const m={artifact:`On the artifact table: ${pick(e.artifacts)}. Inspect its material, wear, markings, and likely everyday use.`,meal:`A local meal is being served near ${pick(e.places)}. Ask what ingredients were common, what was expensive, and who prepared the food.`,gossip:`Rumor: a ${pick(e.people)} says something unusual happened near ${pick(e.places)}. You can investigate or dismiss it as gossip.`,shop:`You enter ${pick(e.places)} with a small budget and compare what people buy for necessity versus status.`,job:`You spend part of the day assisting a ${pick(e.people)} and learning the rhythm, tools, and expectations of the work.`,night:`Night falls. ${pick(e.atmos)}. Public spaces change, some work continues, and other activities begin.`,music:`Listen to the social atmosphere of ${e.title}: where people gather, what entertainment costs, and who gets access.`,postcard:`Postcard draft: “Today I visited ${pick(e.places)}. ${pick(e.atmos)}. The strangest thing I noticed was how different ordinary routines feel here.”`,wardrobe:`Your ${$('#role').textContent||pick(e.roles)} clothing is shaped by work, status, weather, local custom, and what you can afford.`};$('#miniResult').textContent=m[type]}
function titanic(ch){const t={boarding:'Southampton, April 10, 1912. You board among luggage, porters, families, and crew. Explore first impressions before departure.',ship:'The voyage settles into routine: meals, promenade, work shifts, reading rooms, music, class differences, and shipboard schedules.',signals:'Wireless traffic and ice messages become part of the background. This chapter focuses on communication, weather, navigation, and what different people knew.',collision:'Late April 14. The ship strikes an iceberg. There is no score here: the focus is information, uncertainty, movement through the ship, and crew response.',boats:'Evacuation unfolds unevenly. This chapter focuses on locations, instructions, class and access, lifeboat loading, and confusion without turning survival into a game.',aftermath:'The sinking is followed through survivor accounts, inquiries, headlines, memorials, and changes to maritime safety.'};state.era='titanic';$('#titanicChapterResult').textContent=t[ch];renderEra(false)}
function renderDeck(){const e=getEra();const cards=[['Social',`Meet a ${pick(e.people)} near ${pick(e.places)}.`],['Mystery',`Follow a harmless clue through ${pick(e.places)}.`],['Quiet',`Spend an unhurried hour at ${pick(e.places)}.`],['Work',`Assist a ${pick(e.people)} for part of the day.`],['Explore',`Walk from ${pick(e.places)} to ${pick(e.places)}.`]];$('#adventureCards').innerHTML=cards.sort(()=>Math.random()-.5).slice(0,3).map(([a,b])=>`<div class="adventure-card"><b>${a}</b><p>${b}</p><button data-adv="${b.replaceAll('"','&quot;')}">Start</button></div>`).join('');$$('[data-adv]').forEach(b=>b.onclick=()=>doChoice(b.dataset.adv))}
function storyStart(){state.storyStep=1;$('#storyChapter').textContent='Scene 1 of 5';$('#storyMeter').style.width='20%';$('#storyOutput').textContent=`Opening: ${sceneFor('story')}`}
function storyNext(branch=false){if(!state.storyStep)return storyStart();state.storyStep=Math.min(5,state.storyStep+1);const e=getEra();$('#storyChapter').textContent=`Scene ${state.storyStep} of 5`;$('#storyMeter').style.width=`${state.storyStep*20}%`;$('#storyOutput').textContent=`${branch?'Alternate path: ':'Next scene: '}You move toward ${pick(e.places)}. ${pick(e.atmos)}. A ${pick(e.people)} changes what you thought the day would become.`}
function storyEnd(){if(state.storyStep){const m=store.get('htp_memories',[]);m.push({era:getEra().title,scene:$('#storyOutput').textContent});store.set('htp_memories',m);renderMemories()}state.storyStep=0;$('#storyChapter').textContent='Episode closed.';$('#storyMeter').style.width='0';$('#storyOutput').textContent='Your episode is saved as a memory of this visit. Start another whenever you want.'}
function buildRoute(){const e=getEra(), ps=[...e.places].sort(()=>Math.random()-.5).slice(0,3);state.route=ps;state.routeStep=0;$('#routeStops').innerHTML=ps.map((p,i)=>`<div class="route-stop"><b>${i+1}. ${p}</b><p>${['Morning stop','Midday stop','Evening stop'][i]}</p></div>`).join('')}
