function chronicleScene(){const e=getEra();const steps=[
  `Morning begins near ${pick(e.places)}. ${pick(e.atmos)}. A ${pick(e.people)} gives you two ways to spend the first hour.`,
  `By midday, your earlier choice has changed who recognizes you. Someone from ${pick(e.places)} approaches with news that connects to what you did before.`,
  `Evening settles over ${pick(e.places)}. Your path has created one final choice: end quietly, follow one last lead, or spend time with someone you met.`
];return steps[Math.min(chronicle.step,2)]}
