function chronicleNext(){if(!chronicle.opening)return chronicleStart();if(!chronicle.path.length||chronicle.path.length<=chronicle.step){toast('Choose a path first.');return}chronicle.step++;if(chronicle.step>2){$('#chronicleOutput').textContent=`Chronicle complete. ${getEra().title}: ${chronicle.path.join(' → ')}.`;$('#chronicleChoices').innerHTML='';return}$('#chronicleOutput').textContent=chronicleScene();renderChronicleChoices()}
function chronicleSave(){if(!chronicle.path.length)return toast('Start a chronicle first.');const c=store.get('htp_chronicles',[]);c.push({era:getEra().title,text:chronicle.path.join(' → ')});store.set('htp_chronicles',c);renderChronicleLibrary();toast('Chronicle saved.')}
