if(type==='entertainment'){const show=pick(entertainment);out.textContent=`Tonight's local option is ${show} near ${pick(e.places)}. The interesting part is not only the performance—it is who attends, how people behave, what it costs, and who may be excluded.`;actions.innerHTML=`<button data-town-act="attend">🎟️ Attend</button><button data-town-act="watch">👀 Watch the crowd</button><button data-town-act="leave">🌙 Take a quiet walk instead</button>`;}
