function calData(){const e=getEra(),d=livingCalendarData[state.era]||{};return {special:d.special||[`A busy market or public gathering has changed the rhythm around ${pick(e.places)}.`,`A seasonal community event has brought extra visitors to ${pick(e.places)}.`,`A local work cycle, observance, or public gathering is making today feel different.`],home:d.home||[`Inside an ordinary household, meals, cleaning, mending, storage, and work continue around the day’s public events.`,`A quieter domestic scene reveals how much daily life depends on routine, shared labor, and limited resources.`]}}
function relationshipInvite(){const rel=store.get('htp_rel',{}),cur=rel[state.era]||{},e=getEra();const known=Object.entries(cur).filter(([,n])=>n>0).sort((a,b)=>b[1]-a[1]);const person=known.length?known[0][0]:pick(e.people);const n=known.length?known[0][1]:0;const where=pick(e.places);return n?`The ${person} you have spoken with ${n} time${n===1?'':'s'} has left word for you: meet them near ${where}. They have ${pick(['news to share','a small favor to ask','an invitation to a local gathering','something curious they think you should see'])}.`:`No one here knows you well enough to send a personal invitation yet, but a ${person} near ${where} seems open to conversation.`}
function returnPulse(){const key=`htp_last_${state.era}`,last=store.get(key,null),now=Date.now(),e=getEra();store.set(key,now);if(!last)return `This is your first recorded return check for ${e.title}. The portal marks today as the beginning of this era’s living timeline.`;const mins=Math.max(1,Math.round((now-last)/60000));const change=pick([`A familiar place near ${pick(e.places)} is busier than before.`,`Someone you met earlier has moved on to a new task near ${pick(e.places)}.`,`A local notice, rumor, or work schedule has changed since your last check.`,`The weather, crowd, and daily rhythm around ${pick(e.places)} feel different this time.`]);return `You were last here about ${mins} minute${mins===1?'':'s'} ago. ${change}`}
function livingCalendar(type){const e=getEra(),d=calData(),out=$('#calendarResult'),actions=$('#calendarActions');if(!out||!actions)return;actions.innerHTML='';if(type==='special'){out.textContent=`Special day in ${e.title}: ${pick(d.special)}`;actions.innerHTML=`<button data-cal-act="join">Join in</button><button data-cal-act="observe">Watch how people behave</button><button data-cal-act="help">Help with preparations</button>`}if(type==='home'){out.textContent=`Home & Hearth: ${pick(d.home)} A ${pick(e.people)} explains which chores, comforts, and worries are ordinary here.`;actions.innerHTML=`<button data-cal-act="meal">Help with the meal</button><button data-cal-act="chores">Take on a household chore</button><button data-cal-act="talk">Sit and talk with the household</button>`}if(type==='invite'){out.textContent=`Invitation check: ${relationshipInvite()}`;actions.innerHTML=`<button data-cal-act="accept">Accept the invitation</button><button data-cal-act="later">Save it for later</button><button data-cal-act="decline">Politely decline</button>`}if(type==='return'){out.textContent=`Return visit: ${returnPulse()}`;actions.innerHTML=`<button data-cal-act="investigate">See what changed</button><button data-cal-act="revisit">Visit a familiar place</button><button data-cal-act="newperson">Meet someone new</button>`}$$('[data-cal-act]').forEach(b=>b.onclick=()=>{const act=b.dataset.calAct;out.textContent+=`\n\nYou choose to ${act}. ${pick(e.atmos)}. The moment is added to your continuing journey.`;state.thread.push(`calendar: ${act}`);store.set('htp_thread',state.thread);$('#journeyStatus').textContent=`${state.thread.length} connected moments in this visit.`})}


const worldSystems={
  business(){
    const e=getEra(), place=pick(e.places), person=pick(e.people);
    const business=pick([`a small service operating near ${place}`,`a busy seller or workshop near ${place}`,`a locally important trade that depends on regular customers`,`a place where people come for repairs, supplies, food, lodging, or information`]);
    return `Businesses & Services — ${e.title}: You enter ${business}. A ${person} explains what people pay for, what must be ordered ahead, and which services everyone depends on.`;
  },
  economy(){
    const e=getEra(), need=pick(['food','fuel','rent or lodging','clothing repairs','transport','tools','schooling or training','medical help','household supplies']);
    const pressure=pick(['prices have risen','work has been irregular','something must be repaired instead of replaced','cash is limited so barter or credit matters','a seasonal expense has arrived']);
    return `Household Economy — ${e.title}: A household is trying to cover ${need}, but ${pressure}. You help decide what gets paid now, what can wait, and what can be made, borrowed, bartered, or repaired.`;
  },
  transport(){
    const e=getEra(), mode=pick(['walking','wagon or cart','horseback','boat or ship','rail','street transport','a hired ride','a crowded public route']);
    const snag=pick(['the route is slower than expected','weather changes the schedule','a crossing is delayed','space is limited','the road or path is rough','a connection has been missed']);
    return `Travel & Transport — ${e.title}: Your best available option is ${mode}. ${snag}. Reaching ${pick(e.places)} now takes planning instead of a simple click.`;
  },
  weather(){
    const e=getEra(), weather=pick(['heavy rain','thick fog','strong wind','sudden cold','oppressive heat','dusty conditions','a fast-moving storm','snow or sleet']);
    const effect=pick(['shops close early','travel slows down','workers change their routine','crowds move indoors','deliveries are delayed','a public event is altered','people begin sharing warnings and advice']);
    return `Weather Disruption — ${e.title}: ${weather} settles over the area and ${effect}. Your original plan changes with it.`;
  },
  chain(){
    const e=getEra();
    const a=pick(['a late delivery','a missing worker','a crowded market','a broken wheel','a rumor','a public announcement','a sudden weather change']);
    const b=pick(['forces a shop to improvise','changes who shows up at a gathering','sends someone looking for help','creates a shortage somewhere else','draws a crowd to a different part of town']);
    const c=pick(['a new opportunity appears','someone asks you to carry a message','a familiar person needs help','a mystery begins','your route through the day changes']);
    return `Event Chain — ${e.title}: First, ${a}. That ${b}. Before long, ${c}. One small event has now reshaped the rest of your visit.`;
  }
};
function worldSystem(type){
  const out=$('#worldSystemResult'), actions=$('#worldSystemActions'), e=getEra();
  if(!out||!actions||!worldSystems[type]) return;
  out.textContent=worldSystems[type]();
  actions.innerHTML=`<button data-world-act="enter">Follow it</button><button data-world-act="observe">Observe quietly</button><button data-world-act="ask">Ask a local</button><button data-world-act="adapt">Change your plan</button>`;
  $$('[data-world-act]').forEach(b=>b.onclick=()=>{
    const act=b.dataset.worldAct;
    const follow={enter:`You get involved and the situation pulls you toward ${pick(e.places)}.`,observe:`You stay out of the center and notice how ordinary people adjust around you.`,ask:`A ${pick(e.people)} gives you practical advice and a little local context.`,adapt:`You abandon the original plan and choose a route that fits the new conditions.`}[act];
    out.textContent += `

${follow} ${pick(e.atmos)}`;
    state.thread.push(`world system: ${type}/${act}`);
    store.set('htp_thread',state.thread);
    const s=$('#journeyStatus'); if(s) s.textContent=`${state.thread.length} connected moments in this visit.`;
  });
}


const backupKeys=()=>Object.keys(localStorage).filter(k=>k.startsWith('htp_'));
function backUpPortal(){
  const data={format:'HistoricalTimePortal',version:1,savedAt:new Date().toISOString(),items:{}};
  backupKeys().forEach(k=>{data.items[k]=localStorage.getItem(k)});
  const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});
  const url=URL.createObjectURL(blob),a=document.createElement('a');
  a.href=url;a.download='historical-time-portal-backup.json';document.body.append(a);a.click();a.remove();
  setTimeout(()=>URL.revokeObjectURL(url),1000);
  $('#backupStatus').textContent='Backup prepared. Keep the JSON file somewhere safe.';
}
async function restorePortal(file){
  if(!file)return;
  try{
    if(file.size>5_000_000)throw Error('The backup is too large.');
    const data=JSON.parse(await file.text());
    if(data?.format!=='HistoricalTimePortal'||data.version!==1||!data.items||typeof data.items!=='object'||Array.isArray(data.items))throw Error('This is not a compatible Portal backup.');
    const entries=Object.entries(data.items);
    if(entries.length>200||entries.some(([k,v])=>!/^htp_[a-zA-Z0-9_]+$/.test(k)||typeof v!=='string'||v.length>1_000_000))throw Error('This backup contains invalid data.');
    if(!confirm('Restore your Portal backup? This will replace your current Portal progress on this browser.'))return;
    backupKeys().forEach(k=>localStorage.removeItem(k));entries.forEach(([k,v])=>localStorage.setItem(k,v));
    $('#backupStatus').textContent='Backup restored. Refreshing your adventures…';location.reload();
  }catch(e){ $('#backupStatus').textContent='Could not restore: '+e.message }
}

