 $('#planDayBtn').onclick=planDay;$('#saveMomentBtn').onclick=()=>{const m=store.get('htp_memories',[]);m.push({era:getEra().title,scene:$('#sceneText').textContent});store.set('htp_memories',m);renderMemories()};$('#memorySurpriseBtn').onclick=()=>{const m=store.get('htp_memories',[]);if(m.length){const x=pick(m);$('#sceneText').textContent=`Memory from ${x.era}: ${x.scene}`;$('#experiencePanel').scrollIntoView({behavior:'smooth'})}};$('#visitMixerBtn').onclick=mixVisit;$('#continueJourneyBtn').onclick=continueDay;$('#freshThreadBtn').onclick=freshThread;$('#clearRelations').onclick=()=>{const r=store.get('htp_rel',{});delete r[state.era];store.set('htp_rel',r);renderRelations()};
