 $$('.mood-btn').forEach(b=>b.onclick=()=>{const map={relax:'cozy',curious:'explore',social:'roleplay',dramatic:'story',challenge:'games',surprise:pick(Object.keys(modes))};setMode(map[b.dataset.mood]);$('#moodResult').textContent=`Mood set: ${b.textContent.trim()}. The current portal has been reshaped around that choice.`});
