 function init(){document.body.dataset.era='titanic';state.thread=store.get('htp_thread',[]);state.era=eras[store.get('htp_last_era','titanic')]?store.get('htp_last_era','titanic'):'titanic';state.mode=modes[store.get('htp_last_mode','roleplay')]?store.get('htp_last_mode','roleplay'):'roleplay';state.persona=store.get(`htp_persona_${state.era}`,null);wire();$$('.mode-card').forEach(b=>b.classList.toggle('active',b.dataset.mode===state.mode));renderEra();renderWallet();renderPassport();renderJournal();renderCollections();renderQuests();renderAchievements();renderRelations();renderMemories();renderChronicleLibrary();renderNotices();event();buildRoute();window.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.activeElement instanceof HTMLElement)document.activeElement.blur()})}
